<script>
  import { onMount, onDestroy } from 'svelte';
  import { page } from '$app/stores';
  import { userId } from '$lib/stores/auth.js';
  import { authenticatedFetch } from '$lib/services/authenticated-fetch.js';
  import { SURFACES } from '$lib/tennis/domain.js';
  let mounted=false, data=null, failure='', loading=true, signature='', controller, generation=0, surface='all';
  $: demo=$page.url.searchParams.get('demo')==='1';
  $: timezone=$page.url.searchParams.get('tz')||'America/Guayaquil';
  $: query=new URLSearchParams({tz:timezone,...(demo?{demo:'1',...($page.url.searchParams.has('demoAt')?{demoAt:$page.url.searchParams.get('demoAt')}:{})}:{})});
  $: key=`${$page.params.id}:${query}:${$userId}`;
  $: if(mounted&&signature!==key){signature=key;load();}
  $: profile=data?.profile;
  $: players=Object.fromEntries((profile?.players||[]).map(p=>[p.id,p]));
  $: stats=profile?.serviceStats.find(s=>s.surface===surface);
  $: results=(profile?.recent||[]).filter(m=>surface==='all'||m.surface===surface);
  onMount(()=>{mounted=true;});
  onDestroy(()=>{generation++;controller?.abort();});
  async function load(){
    const run=++generation;controller?.abort();controller=new AbortController();loading=true;failure='';data=null;surface='all';
    try{const params=new URLSearchParams(query);params.set('player',$page.params.id);const response=await (demo?fetch(`/api/tennis?${params}`,{signal:controller.signal}):authenticatedFetch(`/api/tennis?${params}`,{signal:controller.signal}));const body=await response.json();if(!response.ok)throw new Error(body.error||body.message||'No se pudo consultar el perfil.');if(run===generation)data=body;}
    catch(e){if(run===generation&&e.name!=='AbortError')failure=e.message;}
    finally{if(run===generation)loading=false;}
  }
  const percent=(n,d)=>d?`${(100*n/d).toFixed(1)}%`:'—';
  const date=value=>new Intl.DateTimeFormat('es',{timeZone:timezone,dateStyle:'medium'}).format(new Date(value));
  const playerLink=id=>`/tennis/player/${encodeURIComponent(id)}?${new URLSearchParams({tz:timezone,...(demo?{demo:'1',demoAt:data.fetchedAt}:{})})}`;
</script>

<svelte:head><title>{profile?.player.name||'Perfil de jugador'} · NioSports Tennis</title><meta name="description" content="Temporada, superficies, últimos partidos y fuentes del perfil de tenis."/></svelte:head>
<div class="profile">
  <a class="back" href={`/tennis?${query}`}>← Volver al calendario de tenis</a>
  {#if loading}<p class="panel" role="status">Cargando ficha del jugador…</p>
  {:else if failure}<section class="panel" role="alert"><h1>No se pudo abrir la ficha</h1><p>{failure}</p><button on:click={load}>Reintentar</button><a href="/tennis?demo=1">Abrir una demostración nueva</a></section>
  {:else if profile}
    <p class="notice">{demo?'DEMOSTRACIÓN · Jugadores y cifras ficticios.':'DATOS DEL PROVEEDOR · Consulta la fecha de actualización.'} {data.stale?'Esta información tiene más de seis horas.':''}</p>
    <header class="identity"><span class="monogram" aria-hidden="true">{profile.player.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><div><p class="eyebrow">TENNIS LAB / PERFIL INDIVIDUAL</p><h1>{profile.player.name}</h1><p>{profile.player.gender==='women'?'Femenino':'Masculino'} · {profile.player.country||'País sin datos'} · {profile.player.rank?`Ranking #${profile.player.rank}`:'Ranking no disponible'}</p></div><span class="season">Temporada {profile.season}<small>Año calendario UTC</small></span></header>
    <div class="kpis"><article><small>Partidos completos</small><strong>{profile.summary.season.played}</strong><span>En el historial recibido de la temporada</span></article><article><small>Victorias / derrotas</small><strong>{profile.summary.season.won} <em>/ {profile.summary.season.played-profile.summary.season.won}</em></strong><span>{percent(profile.summary.season.won,profile.summary.season.played)} de victorias</span></article><article><small>Mejor porcentaje por superficie</small><strong>{SURFACES[profile.summary.bestSurface]||'Sin muestra'}</strong><span>Mínimo 5 partidos por superficie; no es una predicción</span></article></div>
    <div class="columns"><section class="panel"><p class="eyebrow">ADAPTACIÓN A LA PISTA</p><h2>Una temporada, tres superficies</h2>{#each profile.summary.surfaces as row}<div class="surface"><div><strong>{SURFACES[row.surface]}</strong><span>{row.won} de {row.played} ganados · {percent(row.won,row.played)}</span></div><div class="track"><span style={`width:${row.played?100*row.won/row.played:0}%`} class:clay={row.surface==='clay'} class:grass={row.surface==='grass'}></span></div></div>{/each}<p class="muted">La cobertura puede ser parcial. No se cuentan retiros ni partidos sin disputar.</p></section>
    <section class="panel"><p class="eyebrow">DISPONIBILIDAD Y CONTEXTO</p><h2>Estado físico</h2>{#if profile.injury}<h3>{profile.injury.status==='reported'?'Incidencia reportada':'Informe de recuperación'}</h3><p>{profile.injury.title}</p><a href={profile.injury.sourceUrl} target="_blank" rel="noopener noreferrer">Consultar fuente · {date(profile.injury.publishedAt)} ↗</a>{:else}<h3>Sin informe disponible</h3><p class="muted">La ausencia de noticias no confirma que el jugador esté libre de lesiones.</p>{/if}<h3>Próximos partidos recibidos</h3>{#each profile.upcoming as match}<p class="upcoming">vs. <a href={playerLink(match.a===profile.player.id?match.b:match.a)}>{players[match.a===profile.player.id?match.b:match.a]?.name}</a><small>{match.tournament} · {date(match.startAt)} · {SURFACES[match.surface]}</small></p>{:else}<p class="muted">No hay próximos partidos programados en la información recibida.</p>{/each}</section></div>
    <div class="section-heading"><div><p class="eyebrow">EXPLORA LA EVIDENCIA</p><h2>Rendimiento y últimos rivales</h2></div><label>Filtrar superficie<select bind:value={surface}><option value="all">Todas las superficies</option>{#each Object.entries(SURFACES) as [id,label]}<option value={id}>{label}</option>{/each}</select></label></div>
    <div class="columns"><section class="panel"><h2>Saque y puntos de presión</h2>{#if stats}<dl><div><dt>Primer saque dentro</dt><dd>{percent(stats.firstServeIn,stats.servicePoints)}</dd></div><div><dt>Puntos ganados con primer saque</dt><dd>{percent(stats.firstServeWon,stats.firstServeIn)}</dd></div><div><dt>Puntos ganados con segundo saque</dt><dd>{percent(stats.secondServeWon,stats.secondServePoints)}</dd></div><div><dt>Break points salvados</dt><dd>{percent(stats.breakPointsSaved,stats.breakPointsFaced)}</dd></div><div><dt>Break points convertidos</dt><dd>{percent(stats.breaksConverted,stats.breakOpportunities)}</dd></div><div><dt>Aces por partido</dt><dd>{(stats.aces/stats.matches).toFixed(1)}</dd></div><div><dt>Dobles faltas por partido</dt><dd>{(stats.doubleFaults/stats.matches).toFixed(1)}</dd></div></dl><p class="muted">Muestra: {stats.matches} partidos · Actualizado {date(stats.asOf)}. El proveedor puede tener distinta cobertura para estas estadísticas.</p>{:else}<p class="muted">El proveedor no ha entregado estadísticas de saque para esta superficie y temporada.</p>{/if}</section>
    <section class="panel history"><h2>Últimos partidos</h2><p class="muted">Hasta 30 registros recientes; el filtro se aplica a esta muestra. Las fechas usan {timezone}.</p>{#each results as match}<div class="result"><span class="badge" class:loss={match.winner!==profile.player.id} class:exception={match.status!=='completed'}>{match.status==='completed'?(match.winner===profile.player.id?'V':'D'):'•'}</span><div><a href={playerLink(match.a===profile.player.id?match.b:match.a)}>{players[match.a===profile.player.id?match.b:match.a]?.name}</a><small>{match.circuit} · {SURFACES[match.surface]} · {match.status==='retired'?'Retiro':match.status==='walkover'?'Sin disputar':'Completo'}</small></div><time>{date(match.endedAt)}</time></div>{:else}<p class="muted">No hay resultados en esta muestra para la superficie seleccionada.</p>{/each}</section></div>
    <footer>Fuente: {data.provider} · Corte de datos: {date(profile.asOf)} · {new Date(profile.asOf).toISOString()}<br/>Las estadísticas describen resultados recibidos; no garantizan el resultado del próximo partido.</footer>
  {/if}
</div>
<style>
  .profile{max-width:1240px;margin:auto;padding:32px 24px 110px;color:var(--text-primary,#f3f6f5)}a{color:inherit;text-underline-offset:4px}a:hover{color:#b6eb71}.back{display:inline-block;margin-bottom:20px;font-size:14px}.notice{padding:12px 16px;border:1px solid #9ac55b55;border-radius:12px;background:#97c95212;font-size:12px}.identity{display:flex;align-items:center;gap:24px;padding:34px 0}.monogram{display:grid;place-items:center;width:100px;height:100px;border-radius:28px;background:linear-gradient(145deg,#bde983,#2d5d49);color:#10261f;font-size:34px;font-weight:800;flex-shrink:0}.eyebrow{font-size:10px;letter-spacing:2px;color:#91ab9f;font-weight:700}h1{font-size:clamp(28px,4vw,46px);line-height:1.1;margin:10px 0}h2{font-size:20px;margin:10px 0 22px}h3{font-size:16px;margin:24px 0 12px}.identity p{font-size:13px}.season{margin-left:auto;text-align:right;color:#b6df87}.season small{display:block;color:#91ab9f;margin-top:8px;font-size:11px}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.kpis article,.panel{background:var(--bg-secondary,#10251e);border:1px solid #79948a30;border-radius:20px;padding:24px}.kpis small,.kpis span{display:block;font-size:12px;color:#91ab9f}.kpis strong{display:block;font-size:30px;margin:14px 0}.kpis em{font-style:normal;color:#91ab9f}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.surface{margin:25px 0}.surface>div:first-child{display:flex;justify-content:space-between;gap:12px;font-size:13px}.surface span{color:#a7b8b0}.track{height:7px;background:#79948a22;border-radius:8px;margin-top:12px;overflow:hidden}.track span{display:block;height:100%;background:#57b3c1}.track span.clay{background:#d7925c}.track span.grass{background:#a6d66f}.muted{color:#91ab9f;font-size:13px;line-height:1.7}.upcoming small{display:block;font-size:12px;color:#91ab9f;margin-top:8px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:36px 0 12px}.section-heading label{font-size:12px;color:#91ab9f}select{display:block;margin-top:8px;background:var(--bg-secondary,#10251e);color:inherit;border:1px solid #79948a55;padding:10px;border-radius:8px}dl>div{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid #79948a22;padding:14px 0;font-size:13px}dd{margin:0;font-weight:700}.history{max-height:600px;overflow:auto}.result{display:flex;gap:12px;align-items:center;padding:14px 0;border-bottom:1px solid #79948a22;font-size:13px}.badge{background:#a8d97525;color:#b6eb71;border-radius:7px;padding:6px 9px;font-weight:700}.badge.loss{background:#d2767620;color:#e39494}.badge.exception{background:#92a7ad22;color:#bac9ce}.result small{display:block;font-size:10px;color:#91ab9f;margin-top:5px}.result time{margin-left:auto;color:#91ab9f;font-size:11px;white-space:nowrap}footer{font-size:11px;color:#91ab9f;line-height:2;margin-top:24px;overflow-wrap:anywhere}button{padding:10px 16px;border-radius:8px;background:#b6df87;color:#10251e;margin:12px;cursor:pointer}a:focus-visible,button:focus-visible,select:focus-visible{outline:2px solid #b6df87;outline-offset:4px}@media(max-width:760px){.profile{padding:20px 16px 100px}.identity{flex-wrap:wrap;gap:16px}.monogram{width:70px;height:70px;font-size:24px}.identity>div{flex:1;min-width:190px}.season{margin-left:0;text-align:left}.kpis,.columns{grid-template-columns:1fr}.kpis{gap:10px}.kpis article{padding:18px}.kpis strong{font-size:26px;margin:8px 0}.section-heading{align-items:flex-start;flex-direction:column}.panel{padding:20px}.result{gap:8px}.result time{font-size:10px}}
</style>
